#!/usr/bin/env bash
# Fixes a real diagnostic dead-end just hit on the actual Windows service:
# it registered successfully, sc.exe query showed it RUNNING the whole
# time with no crash/Event Log errors, but the Admin Panel showed zero
# progress afterward (no heartbeat, no update download starting) - and
# there was no way to tell whether the background threads were even
# running at all, because EVERY log statement in this whole project
# (visible throughout this entire debugging session) only ever went to
# logging.basicConfig()'s default StreamHandler(sys.stderr).
#
# A Windows SERVICE (pythonservice.exe, no attached console - unlike every
# "... service\opslab_agent_service.py run" console session used to debug
# this so far) is very likely to have sys.stderr as None or otherwise
# unusable - and Python's logging module never lets a handler failure
# raise, so that produces silence: no error, no crash, just nothing,
# anywhere, forever. Exactly what was observed.
#
# agent/main.py's setup_logging() now ALSO attaches a real FileHandler at
# <data dir>/logs/agent.log (C:\ProgramData\OpsLabAgent\logs\agent.log
# on Windows) - a real file doesn't depend on a console existing at all.
# The stream handler is kept too (guarded against sys.stderr being None)
# so console/dev-mode runs still show live output exactly as before.
#
# Verified: logging still reaches the file even with sys.stderr forced to
# None (the real service condition); confirmed the console/stream path is
# completely unaffected when a real stderr exists.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in agent requirements.txt service_files; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

echo "==> Extracting fixed agent/ into this repo"
TMP_EXTRACT="$(mktemp -d)"
base64 -d > "$TMP_EXTRACT/opslab-agent.tar.gz" << 'AGENT_TAR_EOF_MARKER'

AGENT_TAR_EOF_MARKER
tar -xzf "$TMP_EXTRACT/opslab-agent.tar.gz" -C "$TMP_EXTRACT"

if ! grep -q "default_log_dir" "$TMP_EXTRACT/agent/main.py"; then
    echo "    ERROR: fix not found in the extracted agent payload!"
    rm -rf "$TMP_EXTRACT"
    exit 1
fi

rm -f agent/config.py.bak
cp -f "$TMP_EXTRACT/agent/"*.py agent/
echo "    Updated agent/*.py in this repo."

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (served by /install.ps1)"
cp -f "$TMP_EXTRACT/opslab-agent.tar.gz" app/static/installers/opslab-agent.tar.gz
rm -rf "$TMP_EXTRACT"

echo "==> Verifying"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    served agent tarball is readable"

echo ""
echo "Done. On Ewan, re-enroll once more (same as every earlier agent-side fix):"
echo "    irm https://kiosksys.opslabsystems.cloud/install.ps1 -OutFile install.ps1; .\\install.ps1 -Token <fresh-token> -AdminUrl https://kiosksys.opslabsystems.cloud"
echo ""
echo "Then leave it running as the service (do not touch it with a foreground"
echo "console session) and check what it's actually doing via the file, which now"
echo "works even with no console attached at all:"
echo "    Get-Content \"C:\\ProgramData\\OpsLabAgent\\logs\\agent.log\" -Tail 50 -Wait"
